parameters.a2uiDescriptor:
={{ (() => {
  const d = $('ChatGPT DingTalk Card').item.json.body.descriptor;
  if (!d || typeof d !== 'object' || Array.isArray(d)) return d;
  if (d.version === '2' && d.profile === 'universal-v2') return d;
  if (d.version !== '1' || d.profile !== 'universal-v1') return d;
  if (Array.isArray(d.actions) && d.actions.length) {
    throw new Error('Legacy universal-v1 request actions cannot be rendered by the universal-v2 template. Use a legacy action-card workflow or redesign as v2 links.');
  }

  const blocks = Array.isArray(d.blocks) ? d.blocks : [];
  const keyValues = blocks
    .filter((b) => b && typeof b === 'object' && !Array.isArray(b) && b.type === 'keyValue')
    .slice(0, 4)
    .map((b) => ({
      label: String(b.label ?? '指标').slice(0, 100) || '指标',
      value: String(b.value ?? '—').slice(0, 1000) || '—',
    }));

  const defaults = [
    { label: '状态', value: String(d.tone || 'info').toUpperCase() },
    { label: '内容块', value: String(blocks.length) },
    { label: '来源', value: 'ChatGPT' },
    { label: '契约', value: 'universal-v2' },
  ];
  const metrics = [...keyValues];
  for (const item of defaults) {
    if (metrics.length >= 4) break;
    if (!metrics.some((m) => m.label === item.label)) metrics.push(item);
  }
  while (metrics.length < 4) metrics.push({ label: `指标${metrics.length + 1}`, value: '—' });

  const body = blocks.map((b) => {
    if (!b || typeof b !== 'object' || Array.isArray(b)) return '';
    if (b.type === 'text') return String(b.text ?? '');
    if (b.type === 'keyValue') return `- **${String(b.label ?? '信息')}**：${String(b.value ?? '')}`;
    if (b.type === 'list' && Array.isArray(b.items)) return b.items.map((v) => `- ${String(v)}`).join('\n');
    return '';
  }).filter(Boolean).join('\n\n');

  const summary = String(d.summary || blocks.find((b) => b?.type === 'text')?.text || d.title || '通知').slice(0, 1000) || '通知';
  const result = {
    version: '2',
    profile: 'universal-v2',
    title: String(d.title || '通知').slice(0, 200) || '通知',
    summary,
    tone: d.tone || 'info',
    status: String(d.tone || 'info').toUpperCase(),
    source: 'ChatGPT',
    metrics,
    footer: 'ChatGPT · DingTalk universal-v2',
  };
  if (body) result.sections = [{ title: '详情', markdown: body }];
  return result;
})() }}

